import os, pty, fcntl, termios, struct, subprocess, sys, re

EXE = os.environ.get('PLS', '/workspace/executable')

def run(args, cols=250, rows=500, cwd=None, env=None):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    e = dict(os.environ)
    if env: e.update(env)
    p = subprocess.Popen([EXE]+args, stdout=slave, stderr=slave, cwd=cwd, env=e)
    os.close(slave)
    data = b''
    while True:
        try:
            chunk = os.read(master, 65536)
        except OSError:
            break
        if not chunk:
            break
        data += chunk
    p.wait()
    os.close(master)
    return data.decode('utf-8', 'replace')

def lines(args, **kw):
    out = run(args, **kw)
    return [l for l in out.split('\n') if l != '']
