import sys, os, shutil
sys.path.insert(0,'/tmp/h')
from probe import parse_line, clean, lines

def probe(exts, basedir='/tmp/h/pb', prefix='f'):
    shutil.rmtree(basedir, ignore_errors=True); os.makedirs(basedir)
    for i,e in enumerate(exts):
        open(os.path.join(basedir,'%s%d.%s'%(prefix,i,e)),'w').close()
    res = {}
    for l in lines(['-I','0'], cwd=basedir):
        segs = parse_line(l)
        txt = clean(l).rstrip('\r')
        name = txt.split(' ')[-1] if txt.strip() else ''
        icon = ''.join(t.strip() for t,s in segs if t.strip() and s not in ('','0','2'))
        styles = set(s for t,s in segs if s not in ('','0','2') and t.strip())
        # also underline style 4 on name
        for t,s in segs:
            if t.strip() and '4' in s.split(';'):
                styles.add('UL')
        res[name] = (icon, sorted(styles))
    return res

if __name__ == '__main__':
    exts = sys.argv[1:] or sys.stdin.read().split()
    r = probe(exts)
    for name,(ic,st) in sorted(r.items()):
        if ic or st:
            print('%-20s icon=%-12r styles=%s' % (name, ic, st))
