import sys, os, shutil
sys.path.insert(0,'/tmp/h')
from probe import parse_line, clean, lines

def probe(entries, basedir='/tmp/h/pb'):
    shutil.rmtree(basedir, ignore_errors=True); os.makedirs(basedir)
    for i,e in enumerate(entries):
        open(os.path.join(basedir,'f%d.%s'%(i,e)),'w').close()
    res = {}
    for l in lines(['-I','0'], cwd=basedir):
        segs = parse_line(l)
        txt = clean(l).rstrip('\r')
        name = txt.split(' ')[-1]
        prefix = txt[:len(txt)-len(name)]
        icon = prefix.strip()
        styles = sorted(set(s for t,s in segs if s not in ('','0','2') and t.strip()))
        for t,s in segs:
            if t.strip() and '4' in s.split(';'):
                styles.append('UL')
        res[name] = (icon, tuple(sorted(set(styles))))
    return res

def ext_of(name):
    base = name.rsplit('.',1)
    return base[1] if len(base)==2 else None

if __name__=='__main__':
    exts = open(sys.argv[1]).read().split()
    out=[]
    for i in range(0, len(exts), 200):
        r = probe(exts[i:i+200])
        for name,(ic,st) in sorted(r.items()):
            if ic or st:
                out.append('%s\t%r\t%s' % (name, ic, ','.join(st)))
    print('\n'.join(out))
    print('TOTAL %d probed' % len(exts))
