import sys, os, shutil; sys.path.insert(0,'/tmp/h')
from probe import clean, lines

def one(name):
    d='/tmp/h/one'; shutil.rmtree(d, ignore_errors=True); os.makedirs(d)
    open(os.path.join(d,name),'w').close()
    out=[clean(l).rstrip('\r') for l in lines([], cwd=d)]
