import os, stat
found=[]
for root in ['/dev','/sys','/proc','/run','/var','/home','/tmp','/media','/mnt']:
    for dp, dn, fn in os.walk(root, topdown=True):
        for n in dn+fn:
            p=os.path.join(dp,n)
            try: m=os.lstat(p).st_mode
            except Exception: continue
            if (m & 0o170000) == 0o60000: found.append(p)
        if len(found)>5: break
    if len(found)>5: break
print(found[:10] or 'none')
PYEOF"}

