    if matches!(typ, super::node::Typ::Dir) {
        Some(34)
    } else {
        None
    }
}

fn is_word(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

/// Look up the kind for a file name (famous-name table only).
pub fn famous(name: &str) -> Option<&'static Kind> {
    for n in FAMOUS.iter() {
        let matched = match n.mode {
            0 => name == n.key,
            1 => {
                if let Some(rest) = name.strip_prefix(n.key) {
                    rest.is_empty() || !rest.starts_with(is_word)
                } else {
                    false
                }
            }
            _ => name.contains(n.key),
        };
        if matched {
            return Some(&n.kind);
        }
    }
    None
}

/// The "Cargo.lock" child -> "Cargo.toml" parent relationship.
