    if name == "Cargo.lock" {
        Some("Cargo.toml")
    } else {
        None
    }
}

pub fn ext_kind(ext: &str) -> Option<&'static Kind> {
    for e in EXTS.iter() {
        if e.ext == ext {
            return Some(&e.kind);
        }
    }
    for e in EXTS2.iter() {
        if e.ext == ext {
            return Some(&e.kind);
        }
    }
    None
}

/// Split a file name into (leading dots, rest) and the extension.
/// Returns (name without leading dots, extension).
pub fn split_name(name: &str) -> (String, Option<String>) {
    let dots = name.chars().take_while(|c| *c == '.').count();
    let rest = &name[dots..];
    // find the last '.' in rest at index >= 1
    let bytes = rest.as_bytes();
    let mut ext = None;
    let mut stem_len = rest.len();
    for (i, b) in bytes.iter().enumerate() {
        if *b == b'.' && i >= 1 {
            stem_len = i;
            ext = Some(rest[i + 1..].to_string());
        }
    }
    (rest[..stem_len].to_string(), ext)
}

/// Names that are skipped entirely when listing a directory.
pub fn is_skipped(name: &str) -> bool {
    name == ".git"
}
