use std::fs;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};

use crate::kinds::{ext_kind, famous, split_name, Kind};

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
pub enum Typ {
    Dir,
    Symlink,
    Fifo,
    Socket,
    Block,
    Char,
    File,
}

impl Typ {
    pub fn letter(self) -> &'static str {
        match self {
            Typ::Dir => "d",
            Typ::Symlink => "l",
            Typ::Fifo => "p",
            Typ::Socket => "s",
            Typ::Block => "b",
            Typ::Char => "c",
            Typ::File => "f",
        }
    }
    pub fn from_mode(m: u32) -> Typ {
        match m & 0o170000 {
            0o040000 => Typ::Dir,
            0o120000 => Typ::Symlink,
            0o010000 => Typ::Fifo,
            0o140000 => Typ::Socket,
            0o060000 => Typ::Block,
            0o020000 => Typ::Char,
            _ => Typ::File,
        }
    }
}

#[derive(Clone, Debug)]
pub enum Hop {
    Ok { name: String, typ: Typ },
    Broken { name: String },
    Loop { name: String },
    Error { msg: String },
}

#[derive(Clone, Debug)]
pub struct Node {
    pub name: String,
    pub path: PathBuf,
    pub typ: Typ,
    pub hidden: bool,
    pub named: bool,
    pub kind: &'static Kind,
    pub dev: u64,
    pub ino: u64,
    pub nlink: u64,
    pub mode: u32,
    pub uid: u32,
    pub gid: u32,
    pub size: u64,
    pub blocks: u64,
    pub btime: i64,
    pub ctime: i64,
    pub mtime: i64,
    pub atime: i64,
    pub btime_ok: bool,
    pub child: bool,
    pub hops: Vec<Hop>,
}

impl Node {
    pub fn cname(&self) -> String {
        split_name(&self.name).0
    }
    pub fn ext(&self) -> Option<String> {
        split_name(&self.name).1
    }
    pub fn cat(&self) -> u8 {
        if matches!(self.typ, Typ::Dir) {
            0
        } else {
            1
        }
    }
    pub fn importance(&self) -> i8 {
        if self.hidden {
            0
        } else if self.named {
            self.kind.imp
        } else if matches!(self.typ, Typ::Dir | Typ::Symlink) {
            0
        } else {
            self.kind.imp
        }
    }
}

fn hops_for(path: &Path) -> Vec<Hop> {
    let mut out = Vec::new();
    let mut cur = match fs::read_link(path) {
        Ok(t) => t,
        Err(_) => return out,
    };
    let base = path.parent().unwrap_or_else(|| Path::new(""));
    let mut guard = 0usize;
    loop {
        let full: PathBuf = if cur.is_absolute() {
            cur.clone()
        } else {
            base.join(&cur)
        };
        match fs::metadata(&full) {
            Ok(md) => {
                let typ = Typ::from_mode(md.mode());
                out.push(Hop::Ok {
                    name: cur.to_string_lossy().to_string(),
                    typ,
                });
                match fs::symlink_metadata(&full) {
                    Ok(sm) if Typ::from_mode(sm.mode()) == Typ::Symlink => {
                        match fs::read_link(&full) {
                            Ok(t) => {
                                cur = t;
                                guard += 1;
                                if guard > 256 {
                                    break;
                                }
                                continue;
                            }
                            Err(_) => break,
                        }
                    }
                    _ => break,
                }
            }
            Err(e) => {
                let name = cur.to_string_lossy().to_string();
                match e.raw_os_error() {
