use std::collections::HashMap;
use std::sync::OnceLock;

fn passwd_map() -> &'static HashMap<u32, String> {
    static MAP: OnceLock<HashMap<u32, String>> = OnceLock::new();
    MAP.get_or_init(|| {
        let mut m = HashMap::new();
        if let Ok(s) = std::fs::read_to_string("/etc/passwd") {
            for line in s.lines() {
                let f: Vec<&str> = line.split(':').collect();
                if f.len() >= 3 {
                    if let Ok(uid) = f[2].parse::<u32>() {
                        m.entry(uid).or_insert_with(|| f[0].to_string());
                    }
                }
            }
        }
        m
    })
}

fn group_map() -> &'static HashMap<u32, String> {
    static MAP: OnceLock<HashMap<u32, String>> = OnceLock::new();
    MAP.get_or_init(|| {
        let mut m = HashMap::new();
        if let Ok(s) = std::fs::read_to_string("/etc/group") {
            for line in s.lines() {
                let f: Vec<&str> = line.split(':').collect();
                if f.len() >= 3 {
                    if let Ok(gid) = f[2].parse::<u32>() {
                        m.entry(gid).or_insert_with(|| f[0].to_string());
                    }
                }
            }
        }
        m
    })
}

pub fn user_name(uid: u32) -> String {
    match passwd_map().get(&uid) {
        Some(n) => n.clone(),
        None => uid.to_string(),
    }
}

pub fn group_name(gid: u32) -> String {
    match group_map().get(&gid) {
        Some(n) => n.clone(),
        None => gid.to_string(),
    }
}
