use std::cmp::Ordering;

use crate::node::{Hop, Node, Typ};
use crate::opts::{Opts, Unit};

// ---------------------------------------------------------------- styles ----
#[derive(Clone, Copy, Default, PartialEq, Eq, Debug)]
pub struct Style {
    pub bold: bool,
    pub dim: bool,
    pub italic: bool,
    pub underline: bool,
    pub strike: bool,
    pub fg: Option<u8>,
}

impl Style {
    pub fn paint(&self, text: &str) -> String {
        let mut codes: Vec<String> = Vec::new();
        if self.bold {
            codes.push("1".into());
        }
        if self.dim {
            codes.push("2".into());
        }
        if self.italic {
            codes.push("3".into());
        }
        if self.underline {
            codes.push("4".into());
        }
        if self.strike {
            codes.push("9".into());
        }
        if let Some(fg) = self.fg {
            codes.push(fg.to_string());
        }
        if codes.is_empty() {
            text.to_string()
        } else {
            format!("\x1b[{}m{}\x1b[0m", codes.join(";"), text)
        }
    }
    pub fn merge_dim(mut self, dim: bool) -> Style {
        if dim {
            self.dim = true;
        }
        self
    }
}

pub fn paint(st: Style, text: &str, color: bool) -> String {
    if color {
        st.paint(text)
    } else {
        text.to_string()
    }
}

// --------------------------------------------------------------- helpers ----
const ARROW_OK: char = '\u{f0054}';
const ARROW_BROKEN: char = '\u{f17a3}';
const ARROW_LOOP: char = '\u{f0459}';
const ARROW_ERROR: char = '\u{f073a}';

fn dots_of(name: &str) -> (usize, usize) {
    let n = name.chars().take_while(|c| *c == '.').count();
    (n, name.chars().count())
}

/// Renders the name cell of an entry (without trailing column padding).
pub fn name_cell(n: &Node, o: &Opts) -> String {
    let mut out = String::new();
    let fg = n.kind.fg.or(crate::kinds::type_fg(n.typ));
    let base = Style {
        fg,
        italic: n.kind.italic,
        underline: n.kind.underline,
        ..Default::default()
    };
    let dim = n.hidden;
    // tree prefix
    if n.child {
        out.push_str(if o.align { "   \u{2514}\u{2500} " } else { "  \u{2514}\u{2500} " });
    }
    // icon cell
    let icon_w = if o.icons {
        match n.kind.icon {
            Some(i) => i.w as usize,
            None => 1,
        }
    } else {
        0
    };
    let cell_w = if o.icons { icon_w + 1 } else { 0 };
    if o.icons {
        let icon = match n.kind.icon {
            Some(i) => i.ch.to_string(),
            None => " ".to_string(),
        };
        out.push_str(&paint(base.merge_dim(dim), &format!("{} ", icon), o.color));
    }
    if o.align && !n.hidden && cell_w < 3 {
        out.push(' ');
    }
    // name
    let nm = &n.name;
    if o.align && n.hidden {
        let d = nm.chars().take_while(|c| *c == '.').count();
        let (dpart, rest) = nm.split_at(d);
        out.push_str(&paint(Style { dim: true, ..Default::default() }, dpart, o.color));
        out.push_str(&paint(base.merge_dim(true), rest, o.color));
    } else {
        out.push_str(&paint(base.merge_dim(dim), nm, o.color));
    }
    // suffix
    if o.suffix {
        if let Some(s) = crate::kinds::suffix(n.typ) {
            out.push_str(&paint(base.merge_dim(true), &s.to_string(), o.color));
        }
    }
    // symlink target
    if o.sym && matches!(n.typ, Typ::Symlink) {
        for h in n.hops.iter() {
            match h {
                Hop::Ok { name, typ } => {
                    out.push(' ');
                    out.push_str(&paint(Style { fg: Some(35), ..Default::default() }, &ARROW_OK.to_string(), o.color));
                    out.push(' ');
                    let st = Style { fg: crate::kinds::type_fg(*typ), ..Default::default() };
                    out.push_str(&paint(st, name, o.color));
                }
                Hop::Broken { name } => {
                    out.push(' ');
                    out.push_str(&paint(
                        Style { fg: Some(31), ..Default::default() },
                        &format!("{} ", ARROW_BROKEN),
                        o.color,
                    ));
                    out.push_str(&paint(
                        Style { strike: true, fg: Some(31), ..Default::default() },
                        name,
                        o.color,
                    ));
                }
                Hop::Loop { name } => {
                    out.push(' ');
                    out.push_str(&paint(
                        Style { fg: Some(33), ..Default::default() },
                        &format!("{} ", ARROW_LOOP),
                        o.color,
                    ));
                    out.push_str(&paint(Style { fg: Some(33), ..Default::default() }, name, o.color));
                }
                Hop::Error { msg } => {
                    out.push(' ');
                    out.push_str(&paint(
                        Style { fg: Some(31), ..Default::default() },
                        &format!("{} ", ARROW_ERROR),
                        o.color,
                    ));
                    out.push_str(&paint(
                        Style { bold: true, fg: Some(31), ..Default::default() },
                        "error:",
                        o.color,
                    ));
                    out.push_str(&paint(
                        Style { fg: Some(31), ..Default::default() },
                        &format!(" {}", msg),
                        o.color,
                    ));
                }
            }
        }
    }
    out
}

pub fn name_cell_len(n: &Node, o: &Opts) -> usize {
    let mut len = 0usize;
    if n.child {
        len += if o.align { 6 } else { 5 };
    }
    if o.icons {
        len += match n.kind.icon {
            Some(i) => i.w as usize + 1,
            None => 2,
        };
    }
    if o.align && !n.hidden && (if o.icons { match n.kind.icon { Some(i) => i.w as usize + 1, None => 2 } } else { 0 }) < 3 {
        len += 1;
    }
    let nm = &n.name;
    if o.align && n.hidden {
        let d = nm.chars().take_while(|c| *c == '.').count();
        len += d + (nm.chars().count() - d);
    } else {
        len += nm.chars().count();
    }
    if o.suffix {
        if crate::kinds::suffix(n.typ).is_some() {
            len += 1;
        }
    }
    if o.sym && matches!(n.typ, Typ::Symlink) {
        for h in n.hops.iter() {
            match h {
                Hop::Ok { name, .. } => {
                    len += 1 + 1 + 1 + name.chars().count();
                }
                Hop::Broken { name } | Hop::Loop { name } => {
                    len += 1 + 1 + 1 + name.chars().count();
                }
                Hop::Error { msg } => {
                    len += 1 + 1 + 1 + 6 + 1 + msg.chars().count();
                }
            }
        }
    }
    len
}
RSEOF
echo ok"}

