            Some(i) => i.w as usize,
            None => 1,
        }
    } else {
        0
    };
    let cell_w = if o.icons { icon_w + 1 } else { 0 };
    if o.icons {
        let icon = match n.kind.icon {
            Some(i) => i.ch.to_string(),
            None => " ".to_string(),
        };
        out.push_str(&paint(base.merge_dim(dim), &format!("{} ", icon), o.color));
    }
    if o.align && !n.hidden && cell_w < 3 {
        out.push(' ');
    }
    // name
    let nm = &n.name;
    if o.align && n.hidden {
        let d = nm.chars().take_while(|c| *c == '.').count();
        let (dpart, rest) = nm.split_at(d);
        out.push_str(&paint(Style { dim: true, ..Default::default() }, dpart, o.color));
        out.push_str(&paint(base.merge_dim(true), rest, o.color));
    } else {
        out.push_str(&paint(base.merge_dim(dim), nm, o.color));
    }
    // suffix
    if o.suffix {
        if let Some(s) = crate::kinds::suffix(n.typ) {
            out.push_str(&paint(base.merge_dim(true), &s.to_string(), o.color));
        }
    }
    // symlink target
    if o.sym && matches!(n.typ, Typ::Symlink) {
        for h in n.hops.iter() {
            match h {
                Hop::Ok { name, typ } => {
                    out.push(' ');
                    out.push_str(&paint(Style { fg: Some(35), ..Default::default() }, &ARROW_OK.to_string(), o.color));
                    out.push(' ');
                    let st = Style { fg: crate::kinds::type_fg(*typ), ..Default::default() };
                    out.push_str(&paint(st, name, o.color));
                }
                Hop::Broken { name } => {
                    out.push(' ');
                    out.push_str(&paint(
                        Style { fg: Some(31), ..Default::default() },
                        &format!("{} ", ARROW_BROKEN),
                        o.color,
                    ));
                    out.push_str(&paint(
                        Style { strike: true, fg: Some(31), ..Default::default() },
                        name,
                        o.color,
                    ));
                }
                Hop::Loop { name } => {
                    out.push(' ');
                    out.push_str(&paint(
                        Style { fg: Some(33), ..Default::default() },
                        &format!("{} ", ARROW_LOOP),
                        o.color,
                    ));
                    out.push_str(&paint(Style { fg: Some(33), ..Default::default() }, name, o.color));
                }
                Hop::Error { msg } => {
                    out.push(' ');
                    out.push_str(&paint(
                        Style { fg: Some(31), ..Default::default() },
                        &format!("{} ", ARROW_ERROR),
                        o.color,
                    ));
                    out.push_str(&paint(
                        Style { bold: true, fg: Some(31), ..Default::default() },
                        "error:",
                        o.color,
                    ));
                    out.push_str(&paint(
                        Style { fg: Some(31), ..Default::default() },
                        &format!(" {}", msg),
                        o.color,
                    ));
                }
            }
        }
    }
    out
}

pub fn name_cell_len(n: &Node, o: &Opts) -> usize {
    let mut len = 0usize;
    if n.child {
        len += if o.align { 6 } else { 5 };
    }
    if o.icons {
        len += match n.kind.icon {
            Some(i) => i.w as usize + 1,
            None => 2,
        };
    }
    if o.align && !n.hidden && (if o.icons { match n.kind.icon { Some(i) => i.w as usize + 1, None => 2 } } else { 0 }) < 3 {
        len += 1;
    }
    let nm = &n.name;
    if o.align && n.hidden {
        let d = nm.chars().take_while(|c| *c == '.').count();
        len += d + (nm.chars().count() - d);
    } else {
        len += nm.chars().count();
    }
    if o.suffix {
        if crate::kinds::suffix(n.typ).is_some() {
            len += 1;
        }
    }
    if o.sym && matches!(n.typ, Typ::Symlink) {
        for h in n.hops.iter() {
            match h {
                Hop::Ok { name, .. } => {
                    len += 1 + 1 + 1 + name.chars().count();
                }
                Hop::Broken { name } | Hop::Loop { name } => {
                    len += 1 + 1 + 1 + name.chars().count();
                }
                Hop::Error { msg } => {
                    len += 1 + 1 + 1 + 6 + 1 + msg.chars().count();
                }
            }
        }
    }
    len
}
