fn perm_string(mode: u32) -> String {
    let mut out = String::with_capacity(11);
    const BITS: [(u32, char); 3] = [(0o4, 'r'), (0o2, 'w'), (0o1, 'x')];
    for g in 0..3 {
        let shift = 6 - 3 * g;
        for (bit, ch) in BITS.iter() {
            if mode & (*bit << shift) != 0 {
                out.push(*ch);
            } else {
                out.push('-');
            }
        }
        out.push(' ');
    }
    out.pop();
    // special bits
    if mode & 0o4000 != 0 {
        let i = 2;
        let bytes = unsafe { out.as_mut_vec() };
        bytes[i] = if bytes[i] == b'x' { b's' } else { b'S' };
    }
    if mode & 0o2000 != 0 {
        let i = 6;
        let bytes = unsafe { out.as_mut_vec() };
        bytes[i] = if bytes[i] == b'x' { b's' } else { b'S' };
    }
    if mode & 0o1000 != 0 {
        let i = 10;
        let bytes = unsafe { out.as_mut_vec() };
        bytes[i] = if bytes[i] == b'x' { b't' } else { b'T' };
    }
    out
}

fn fmt_time(secs: i64) -> String {
    const MONTHS: [&str; 12] = [
        "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
    ];
    unsafe {
        let t = secs as libc::time_t;
        let mut tm: libc::tm = std::mem::zeroed();
        libc::localtime_r(&t, &mut tm);
        let mon = MONTHS[tm.tm_mon.clamp(0, 11) as usize];
        let h = tm.tm_hour;
        let h12 = ((h + 11) % 12) + 1;
        let ap = if h < 12 { "am" } else { "pm" };
        format!(
            "{:04}-{}-{:02} {:02}:{:02}{}",
            tm.tm_year + 1900,
            mon,
            tm.tm_mday,
            h12,
            tm.tm_min,
            ap
        )
    }
}

pub fn size_parts(bytes: u64, unit: Unit) -> (String, String) {
    match unit {
        Unit::None => (bytes.to_string(), "B".to_string()),
        Unit::Binary | Unit::Decimal => {
            let names: [&str; 7] = if matches!(unit, Unit::Binary) {
                ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"]
            } else {
                ["B", "kB", "MB", "GB", "TB", "PB", "EB"]
            };
            let base: f64 = if matches!(unit, Unit::Binary) { 1024.0 } else { 1000.0 };
            let mut v = bytes as f64;
            let mut i = 0usize;
            while v >= base && i < names.len() - 1 {
                v /= base;
                i += 1;
            }
            (format!("{:.1}", v), names[i].to_string())
        }
    }
}

pub fn date_fg(d: Det) -> u8 {
    match d {
        Det::Btime => 32,
        Det::Ctime | Det::Mtime => 33,
        Det::Atime => 34,
        _ => 0,
    }
}

/// Cell content (styled, unpadded) plus its display length in characters.
pub fn cell(n: &Node, d: Det, o: &Opts) -> (String, usize) {
    match d {
        Det::Dev => (n.dev.to_string(), n.dev.to_string().chars().count()),
        Det::Ino => (n.ino.to_string(), n.ino.to_string().chars().count()),
        Det::Nlink => (n.nlink.to_string(), n.nlink.to_string().chars().count()),
        Det::Typ => {
            let s = n.typ.letter().to_string();
            let st = match n.typ {
                crate::node::Typ::Dir => Style { fg: Some(34), ..Default::default() },
                crate::node::Typ::File => Style { dim: true, ..Default::default() },
                _ => Style::default(),
            };
            (paint(st, &s, o.color), 1)
        }
        Det::Perm => {
            let s = perm_string(n.mode);
            let len = s.chars().count();
            if !o.color {
                return (s, len);
            }
            let mut out = String::new();
            for (i, c) in s.chars().enumerate() {
                if c == ' ' {
                    out.push(' ');
                } else {
                    let st = match c {
                        'r' => Style { fg: Some(33), ..Default::default() },
                        'w' => Style { fg: Some(31), ..Default::default() },
                        'x' | 's' | 't' => Style { fg: Some(32), ..Default::default() },
                        _ => Style { dim: true, ..Default::default() },
                    };
                    out.push_str(&st.paint(&c.to_string()));
                }
            }
            (out, len)
        }
        Det::Oct => {
            let s = format!("{:03o}", n.mode & 0o7777);
            let len = s.chars().count();
            if !o.color {
                return (s, len);
            }
            let mut out = String::new();
            for (i, c) in s.chars().enumerate() {
                let st = match i {
                    0 => Style { fg: Some(34), ..Default::default() },
                    1 => Style { dim: true, fg: Some(34), ..Default::default() },
                    _ => Style { dim: true, ..Default::default() },
                };
                out.push_str(&st.paint(&c.to_string()));
            }
            (out, len)
        }
        Det::User => {
            let s = crate::users::user_name(n.uid);
            let len = s.chars().count();
            (paint(Style { bold: true, fg: Some(34), ..Default::default() }, &s, o.color), len)
        }
        Det::Uid => {
            let s = n.uid.to_string();
            let len = s.chars().count();
            (paint(Style { bold: true, fg: Some(34), ..Default::default() }, &s, o.color), len)
        }
        Det::Group => {
            let s = crate::users::group_name(n.gid);
            let len = s.chars().count();
            (paint(Style { dim: true, ..Default::default() }, &s, o.color), len)
        }
        Det::Gid => {
            let s = n.gid.to_string();
            let len = s.chars().count();
            (paint(Style { dim: true, ..Default::default() }, &s, o.color), len)
        }
        Det::Blocks => {
            let s = n.blocks.to_string();
            let len = s.chars().count();
            (s, len)
        }
        Det::Git => ("    ".to_string(), 4),
        Det::Size => {
            if matches!(n.typ, crate::node::Typ::Dir) {
                (String::new(), 0)
            } else {
                let (v, u) = size_parts(n.size, o.unit);
                let mut out = String::new();
                out.push_str(&paint(Style { bold: true, ..Default::default() }, &v, o.color));
                out.push(' ');
                let (pre, last) = u.split_at(u.chars().count() - 1);
                out.push_str(pre);
                out.push_str(&paint(Style { dim: true, ..Default::default() }, last, o.color));
                (out, v.chars().count() + 1 + u.chars().count())
            }
        }
        Det::Btime | Det::Ctime | Det::Mtime | Det::Atime => {
            let secs = match d {
                Det::Btime => n.btime,
                Det::Ctime => n.ctime,
                Det::Mtime => n.mtime,
                _ => n.atime,
            };
            let s = fmt_time(secs);
            let len = s.chars().count();
            if !o.color {
                return (s, len);
            }
            let (date, rest) = s.split_at(11);
            let st = Style {
                bold: true,
                fg: Some(date_fg(d)),
                ..Default::default()
            };
            (format!("{}{}", st.paint(date), rest), len)
        }
    }
}

/// Special width computation for the size column (value + unit widths).
pub fn size_widths(nodes: &[Node], o: &Opts) -> (usize, usize) {
    let mut w = 0usize;
    let mut u = 0usize;
    for n in nodes {
        if matches!(n.typ, crate::node::Typ::Dir) {
            continue;
        }
        let (v, uu) = size_parts(n.size, o.unit);
        w = w.max(v.chars().count());
        u = u.max(uu.chars().count());
    }
    (w, u)
}
