        Det::Atime => "Accessed",
        Det::Git => "Git",
    }
}

pub fn right(d: Det) -> bool {
    matches!(
        d,
        Det::Dev | Det::Ino | Det::Nlink | Det::Oct | Det::Uid | Det::Gid | Det::Size | Det::Blocks | Det::Git | Det::Typ
    )
}

fn perm_string(mode: u32) -> String {
    let mut out = String::with_capacity(11);
    const BITS: [(u32, char); 3] = [(0o4, 'r'), (0o2, 'w'), (0o1, 'x')];
    for g in 0..3 {
        let shift = 6 - 3 * g;
        for (bit, ch) in BITS.iter() {
            if mode & (*bit << shift) != 0 {
                out.push(*ch);
            } else {
                out.push('-');
            }
        }
        out.push(' ');
    }
    out.pop();
    // special bits
    if mode & 0o4000 != 0 {
        let i = 2;
        let bytes = unsafe { out.as_mut_vec() };
        bytes[i] = if bytes[i] == b'x' { b's' } else { b'S' };
    }
    if mode & 0o2000 != 0 {
        let i = 6;
        let bytes = unsafe { out.as_mut_vec() };
        bytes[i] = if bytes[i] == b'x' { b's' } else { b'S' };
    }
    if mode & 0o1000 != 0 {
        let i = 10;
        let bytes = unsafe { out.as_mut_vec() };
        bytes[i] = if bytes[i] == b'x' { b't' } else { b'T' };
    }
    out
}

fn fmt_time(secs: i64) -> String {
    const MONTHS: [&str; 12] = [
        "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
    ];
    unsafe {
        let t = secs as libc::time_t;
        let mut tm: libc::tm = std::mem::zeroed();
        libc::localtime_r(&t, &mut tm);
        let mon = MONTHS[tm.tm_mon.clamp(0, 11) as usize];
        let h = tm.tm_hour;
        let h12 = ((h + 11) % 12) + 1;
        let ap = if h < 12 { "am" } else { "pm" };
        format!(
            "{:04}-{}-{:02} {:02}:{:02}{}",
            tm.tm_year + 1900,
            mon,
            tm.tm_mday,
            h12,
            tm.tm_min,
            ap
        )
    }
}

pub fn size_parts(bytes: u64, unit: Unit) -> (String, String) {
    match unit {
        Unit::None => (bytes.to_string(), "B".to_string()),
        Unit::Binary | Unit::Decimal => {
            let names: [&str; 7] = if matches!(unit, Unit::Binary) {
                ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"]
            } else {
                ["B", "kB", "MB", "GB", "TB", "PB", "EB"]
            };
            let base: f64 = if matches!(unit, Unit::Binary) { 1024.0 } else { 1000.0 };
            let mut v = bytes as f64;
            let mut i = 0usize;
            while v >= base && i < names.len() - 1 {
                v /= base;
                i += 1;
            }
            (format!("{:.1}", v), names[i].to_string())
        }
    }
}

pub fn date_fg(d: Det) -> u8 {
    match d {
        Det::Btime => 32,
        Det::Ctime | Det::Mtime => 33,
        Det::Atime => 34,
        _ => 0,
    }
}

