use std::ffi::OsStr;

fn env_nonempty(name: &str) -> bool {
    match std::env::var_os(name) {
        Some(v) => !v.is_empty(),
        None => false,
    }
}

fn is_terminal(fd: i32) -> bool {
    unsafe { libc::isatty(fd) == 1 }
}

/// Colour decision used for the listing output (pls's own logic).
pub fn use_color(fd: i32) -> bool {
    if let Some(v) = std::env::var_os("CLICOLOR_FORCE") {
        if v != OsStr::new("0") {
            return true;
        }
    }
    if env_nonempty("NO_COLOR") {
        return false;
    }
    if !is_terminal(fd) {
        return false;
    }
    if let Some(v) = std::env::var_os("CLICOLOR") {
        if v == OsStr::new("0") {
            return false;
        }
    }
    true
}

/// Colour decision used by anstream for error output.
pub fn anstream_color(fd: i32) -> bool {
    let clicolor = std::env::var_os("CLICOLOR").map(|v| v != OsStr::new("0"));
    let clicolor_enabled = clicolor.unwrap_or(false);
    let clicolor_disabled = !clicolor.unwrap_or(true);
    if env_nonempty("NO_COLOR") {
        return false;
    }
    if env_nonempty("CLICOLOR_FORCE") {
        return true;
    }
    if clicolor_disabled {
        return false;
    }
    if is_terminal(fd) {
        let term_ok = match std::env::var_os("TERM") {
            None => false,
            Some(t) => t != OsStr::new("dumb"),
        };
        if term_ok || clicolor_enabled || env_nonempty("CI") {
            return true;
        }
    }
    false
}
