use std::ffi::OsStr;

use crate::clap::builder::{Arg, Command, TypedValueParser, ValueParser};
use crate::clap::error::ErrorKind;
use crate::errstyle;

pub use crate::regex_crate::Regex;

#[derive(Clone)]
pub struct RegexParser;

impl TypedValueParser for RegexParser {
    type Value = String;

    fn parse_ref(
        &self,
        cmd: &Command,
        arg: Option<&Arg>,
        value: &OsStr,
    ) -> Result<String, crate::clap::Error> {
        let s = value.to_string_lossy().into_owned();
        match Regex::new(&s) {
            Ok(_) => Ok(s),
            Err(e) => {
                let arg_s = arg.map(|a| a.to_string()).unwrap_or_else(|| "...".to_owned());
                let body = format!(
                    "invalid value '{}' for '{}': {}",
                    errstyle::invalid(&s),
                    errstyle::literal(&arg_s),
                    e
                );
                Err(crate::clap::Error::raw(
                    ErrorKind::ValueValidation,
                    errstyle::error_message(&body),
                )
                .with_cmd(cmd))
            }
        }
    }
}
