use std::ffi::OsStr;
use std::fs;
use std::io::Write;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};

use clap::ArgMatches;
use filters::RegexParser;
use node::{Node, Typ};
use opts::{SortBase, SortKey, Tristate, TypFilter, Unit};

// ------------------------------------------------------------- utilities ----
fn os_to_string(s: &OsStr) -> String {
    s.to_string_lossy().into_owned()
}

fn pad_left(s: &str, w: usize) -> String {
    let n = s.chars().count();
    if n >= w {
        s.to_string()
    } else {
        format!("{}{}", " ".repeat(w - n), s)
    }
}

fn pad_right(s: &str, w: usize) -> String {
    let n = s.chars().count();
    if n >= w {
        s.to_string()
    } else {
        format!("{}{}", s, " ".repeat(w - n))
    }
}

// ------------------------------------------------------------- terminal -----
fn term_width() -> Option<usize> {
    unsafe {
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(1, libc::TIOCGWINSZ, &mut ws as *mut libc::winsize) == 0 && ws.ws_col > 0 {
            Some(ws.ws_col as usize)
        } else {
            None
        }
    }
}

// ---------------------------------------------------------------- blocks ----
enum Block {
    StatErr { path: String, msg: String },
    Dir { path: String, nodes: Vec<Node>, err: Option<String> },
    File { node: Node },
}

fn dir_nodes(dir: &Path, o: &opts::Opts) -> (Vec<Node>, Option<String>) {
    let mut nodes = Vec::new();
    let rd = match fs::read_dir(dir) {
        Ok(r) => r,
        Err(e) => return (nodes, Some(e.to_string())),
    };
    for ent in rd {
        let ent = match ent {
            Ok(e) => e,
            Err(_) => continue,
        };
        let name = os_to_string(ent.file_name().as_os_str());
        if kinds::is_skipped(&name) {
            continue;
        }
        let full = dir.join(ent.file_name());
        let n = match node::make(&full, &name) {
            Some(n) => n,
            None => continue,
        };
        // filters
        if !o.typs.is_empty() {
            let mut ok = false;
            for t in &o.typs {
                let m = match t {
                    TypFilter::All => true,
                    TypFilter::None => false,
                    TypFilter::Dir => matches!(n.typ, Typ::Dir),
                    TypFilter::Symlink => matches!(n.typ, Typ::Symlink),
                    TypFilter::Fifo => matches!(n.typ, Typ::Fifo),
                    TypFilter::Socket => matches!(n.typ, Typ::Socket),
                    TypFilter::Block => matches!(n.typ, Typ::Block),
                    TypFilter::Char => matches!(n.typ, Typ::Char),
                    TypFilter::File => matches!(n.typ, Typ::File),
                };
                if m {
                    ok = true;
                    break;
                }
            }
            if !ok {
                continue;
            }
        }
        if n.importance() < o.imp {
            continue;
        }
        if o.excludes.iter().any(|r| r.is_match(&name)) {
            continue;
        }
        if !o.onlies.is_empty() && !o.onlies.iter().any(|r| r.is_match(&name)) {
            continue;
        }
        nodes.push(n);
    }
    (nodes, None)
}

fn build(o: &opts::Opts, paths: &[OsStr]) -> Vec<Block> {
    let mut blocks: Vec<Block> = Vec::new();
    for p in paths {
        let path = Path::new(p);
        let md = match fs::symlink_metadata(path) {
            Ok(m) => m,
            Err(e) => {
                blocks.push(Block::StatErr {
                    path: os_to_string(p),
                    msg: e.to_string(),
                });
                continue;
            }
        };
        let typ = Typ::from_mode(md.mode());
        if matches!(typ, Typ::Dir) {
            let (nodes, err) = dir_nodes(path, o);
            blocks.push(Block::Dir {
                path: os_to_string(p),
                nodes,
                err,
            });
        } else {
            let name = path
                .file_name()
                .map(|f| os_to_string(f))
                .unwrap_or_else(|| os_to_string(p));
            if let Some(n) = node::make(path, &name) {
                blocks.push(Block::File { node: n });
            }
        }
    }
    blocks
}

// ----------------------------------------------------------------- sort -----
fn user_key(n: &Node) -> String {
    crate::users::user_name(n.uid)
}
fn group_key(n: &Node) -> String {
    crate::users::group_name(n.gid)
}

fn cmp_by(a: &Node, b: &Node, base: SortBase) -> std::cmp::Ordering {
    use std::cmp::Ordering::*;
    match base {
        SortBase::Dev => a.dev.cmp(&b.dev),
        SortBase::Ino => a.ino.cmp(&b.ino),
        SortBase::Nlink => a.nlink.cmp(&b.nlink),
        SortBase::Typ => a.typ.cmp(&b.typ),
        SortBase::Cat => a.cat().cmp(&b.cat()),
        SortBase::User => user_key(a).cmp(&user_key(b)),
        SortBase::Uid => a.uid.cmp(&b.uid),
        SortBase::Group => group_key(a).cmp(&group_key(b)),
        SortBase::Gid => a.gid.cmp(&b.gid),
        SortBase::Size => a.size.cmp(&b.size),
        SortBase::Blocks => a.blocks.cmp(&b.blocks),
        SortBase::Btime => a.btime.cmp(&b.btime),
        SortBase::Ctime => a.ctime.cmp(&b.ctime),
        SortBase::Mtime => a.mtime.cmp(&b.mtime),
        SortBase::Atime => a.atime.cmp(&b.atime),
        SortBase::Name => a.name.cmp(&b.name),
        SortBase::Cname => a.cname().cmp(&b.cname()).then(a.typ.cmp(&b.typ)),
        SortBase::Ext => {
            let ea = a.ext().unwrap_or_default();
            let eb = b.ext().unwrap_or_default();
            ea.cmp(&eb)
        }
        SortBase::None => Equal,
    }
}

fn sort_nodes(nodes: &mut Vec<Node>, sorts: &[SortKey]) {
    nodes.sort_by(|a, b| {
        for k in sorts {
            let mut o = cmp_by(a, b, k.base);
            if k.rev {
                o = o.reverse();
            }
            if o != std::cmp::Ordering::Equal {
                return o;
            }
        }
        std::cmp::Ordering::Equal
    });
}

fn collapse(nodes: &mut Vec<Node>, on: bool) {
    if !on {
        return;
    }
    for n in nodes.iter_mut() {
        if let Some(parent) = kinds::parent_name_of(&n.name) {
            if nodes.iter().any(|m| m.name == parent && !std::ptr::eq(m, n)) {
                n.child = true;
            }
        }
    }
}

fn move_children(nodes: &mut Vec<Node>) {
    let mut kids: std::collections::HashMap<String, Vec<usize>> = std::collections::HashMap::new();
    for (i, n) in nodes.iter().enumerate() {
        if n.child {
            if let Some(p) = kinds::parent_name_of(&n.name) {
                kids.entry(p.to_string()).or_default().push(i);
            }
        }
    }
    let mut out: Vec<Node> = Vec::new();
    for (i, n) in nodes.iter().enumerate() {
        if n.child {
            continue;
        }
        out.push(n.clone());
        if let Some(idxs) = kids.get(&n.name) {
            for &j in idxs {
                out.push(nodes[j].clone());
            }
        }
        let _ = i;
    }
    *nodes = out;
}

// --------------------------------------------------------------- render -----
const HEADER_STYLE: &str = "\x1b[1;4;3m";

fn header_row(nodes: &[Node], o: &opts::Opts) -> String {
    let dets = &o.dets;
    let mut widths: Vec<usize> = Vec::with_capacity(dets.len());
    let mut size_w: Option<(usize, usize)> = None;
    for d in dets.iter() {
        if matches!(d, detail::Det::Size) {
            let (vw, uw) = detail::size_widths(nodes, o);
            size_w = Some((vw, uw));
            widths.push(detail::header(*d).chars().count().max(vw + 1 + uw));
        } else {
            let mut w = detail::header(*d).chars().count();
            for n in nodes.iter() {
                w = w.max(detail::cell(n, *d, o).1);
            }
            widths.push(w);
        }
    }
    let mut out = String::new();
    let colored = o.color;
    for (i, d) in dets.iter().enumerate() {
        let h = detail::header(*d);
        let w = widths[i];
        let padded = if detail::right(*d) {
            pad_left(h, w)
        } else {
            pad_right(h, w)
        };
        let txt = if i + 1 < dets.len() {
            format!("{} ", padded)
        } else {
            padded
        };
        if colored {
            out.push_str(&format!("{}{}\x1b[0m", HEADER_STYLE, txt));
        } else {
            out.push_str(&txt);
        }
    }
    out
}

fn size_cell(n: &Node, o: &opts::Opts, vw: usize, uw: usize) -> (String, usize) {
    if matches!(n.typ, Typ::Dir) {
        return (" ".repeat(vw + 1 + uw), vw + 1 + uw);
    }
    let (v, u) = detail::size_parts(n.size, o.unit);
    let mut out = String::new();
    let vp = pad_left(&v, vw);
    out.push_str(&render::paint(render::Style { bold: true, ..Default::default() }, &vp, o.color));
    out.push(' ');
    let (pre, last) = u.split_at(u.chars().count() - 1);
    let up = pad_right(pre, uw - 1);
    out.push_str(&up);
    out.push_str(&render::paint(
        render::Style { dim: true, ..Default::default() },
        last,
        o.color,
    ));
    (out, vw + 1 + uw)
}

fn detail_row(n: &Node, o: &opts::Opts, widths: &[usize], size_w: (usize, usize)) -> String {
    let mut out = String::new();
    for (i, d) in o.dets.iter().enumerate() {
        let (txt, len) = if matches!(d, detail::Det::Size) {
            size_cell(n, o, size_w.0, size_w.1)
        } else {
            detail::cell(n, *d, o)
        };
        let w = widths[i];
        if detail::right(*d) {
            out.push_str(&" ".repeat(w.saturating_sub(len)));
            out.push_str(&txt);
        } else {
            out.push_str(&txt);
            out.push_str(&" ".repeat(w.saturating_sub(len)));
        }
        if i + 1 < o.dets.len() {
            out.push(' ');
        }
    }
    out.push_str(&render::name_cell(n, o));
    out.push('\n');
    out
}

fn render_listing(out: &mut String, nodes: &[Node], o: &opts::Opts) {
    if !o.dets.is_empty() {
        let mut widths = Vec::with_capacity(o.dets.len());
        let mut size_w = (0usize, 0usize);
        for d in o.dets.iter() {
            if matches!(d, detail::Det::Size) {
                size_w = detail::size_widths(nodes, o);
                widths.push(detail::header(*d).chars().count().max(size_w.0 + 1 + size_w.1));
            } else {
                let mut w = detail::header(*d).chars().count();
                for n in nodes.iter() {
                    w = w.max(detail::cell(n, *d, o).1);
                }
                widths.push(w);
            }
        }
        if o.header {
            out.push_str(&header_row(nodes, o));
            out.push('\n');
        }
        for n in nodes.iter() {
            out.push_str(&detail_row(n, o, &widths, size_w));
        }
        return;
    }
    // grid or single column
    if o.grid && nodes.len() > 1 {
        if let Some(tw) = o.width {
            if let Some(rows) = grid_rows(nodes, o, tw) {
                for r in rows {
                    out.push_str(&r);
                    out.push('\n');
                }
                return;
            }
        }
    }
    for n in nodes.iter() {
        out.push_str(&render::name_cell(n, o));
        out.push('\n');
    }
}

fn grid_rows(nodes: &[Node], o: &opts::Opts, tw: usize) -> Option<Vec<String>> {
    let cells: Vec<(String, usize)> = nodes
        .iter()
        .map(|n| (render::name_cell(n, o), render::name_cell_len(n, o)))
        .collect();
    let max_cell = cells.iter().map(|(_, l)| *l).max()?;
    if max_cell == 0 {
        return None;
    }
    let colwidth = max_cell + 2;
    let n = nodes.len();
    let mut chosen: Option<usize> = None;
    for r in 1..=n {
        let k = (n + r - 1) / r;
        let line = (k - 1) * colwidth + max_cell;
        if line <= tw {
            chosen = Some(r);
            break;
        }
    }
    let r = chosen?;
    let k = (n + r - 1) / r;
    if k <= 1 {
        return None;
    }
    let nrows = r;
    let mut lines: Vec<String> = vec![String::new(); nrows];
    for (idx, (txt, len)) in cells.iter().enumerate() {
        let (row, col) = if o.down {
            (idx % nrows, idx / nrows)
        } else {
            (idx / k, idx % k)
        };
        let is_last = if o.down { col + 1 == k || (col == k - 1) } else { col + 1 == k };
        let target = if is_last { max_cell } else { colwidth };
        let last_in_row = if o.down {
            idx + nrows >= n
        } else {
            idx % k == k - 1
        };
        let target = if last_in_row { max_cell } else { colwidth };
        lines[row].push_str(txt);
        lines[row].push_str(&" ".repeat(target.saturating_sub(*len)));
    }
    Some(lines)
}

// ------------------------------------------------------------------ main ----
fn run() -> i32 {
    let mut cmd = cli::build();
    let m = match cmd.try_get_matches_from_mut(std::env::args_os()) {
        Ok(m) => m,
        Err(e) => {
            let _ = e.print();
            return e.exit_code();
        }
    };
    let color = color::use_color(1);
    let o = build_opts(&m, color);
    let paths: Vec<OsStr> = m
        .get_many::<OsStr>("paths")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let blocks = build(&o, &paths);
    let mut out = String::new();
    let multi = paths.len() > 1;
    // errors
    for b in blocks.iter() {
        if let Block::StatErr { path, msg } = b {
            out.push_str(&format!("{}:\n\t{} {}\n", err_bold(path), err_label(), msg));
        }
    }
    // files
    let files: Vec<&Node> = blocks
        .iter()
        .filter_map(|b| match b {
            Block::File { node } => Some(node),
            _ => None,
        })
        .collect();
    if !files.is_empty() {
        let owned: Vec<Node> = files.iter().map(|n| (*n).clone()).collect();
        render_listing(&mut out, &owned, &o);
    }
    // dirs
    for b in blocks.iter() {
        if let Block::Dir { path, nodes, err } = b {
            if multi {
                out.push('\n');
            }
            out.push_str(&format!("{}:\n", err_bold(path)));
            match err {
                Some(msg) => {
                    out.push_str(&format!("{} {}\n", err_label(), msg));
                }
                None => render_listing(&mut out, nodes, &o),
            }
        }
    }
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(out.as_bytes());
    let _ = lock.flush();
    0
}

fn err_bold(s: &str) -> String {
    if color::use_color(2) {
        format!("\x1b[1m{}\x1b[0m", s)
    } else {
        s.to_string()
    }
}

fn err_label() -> String {
    if color::use_color(2) {
        format!("\x1b[1;31merror:\x1b[0m")
    } else {
        "error:".to_string()
    }
}

fn build_opts(m: &ArgMatches, color: bool) -> opts::Opts {
    let bool_of = |name: &str, dflt: bool| -> bool {
        match m.get_one::<String>(name).map(|s| s.as_str()) {
            Some("true") => true,
            Some("false") => false,
            _ => dflt,
        }
    };
    let unit = match m.get_one::<String>("unit").map(|s| s.as_str()) {
        Some("decimal") => Unit::Decimal,
        Some("none") => Unit::None,
