def run(exe, args, cwd, env=None):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack('HHHH', 500, 250, 0, 0))
    e=dict(os.environ); 
    if env: e.update(env)
    p=subprocess.Popen([exe]+args, stdout=slave, stderr=slave, cwd=cwd, env=e)
