/// Marks dependent nodes and groups them behind their principal node.
fn group_sort(nodes: &mut Vec<Node>, sorts: &[SortKey], collapse: bool) {
    if collapse {
        for n in nodes.iter_mut() {
            if kinds::parent_name_of(&n.name).is_some() {
                n.child = true;
            }
        }
