        for i in 0..nodes.len() {
            if nodes[i].child {
                if let Some(p) = kinds::parent_name_of(&nodes[i].name) {
                    if names.iter().any(|m| m == p && *m != nodes[i].name) {
                        nodes[i].has_parent = true;
                    }
                }
            }
        }
    }
    if sorts.len() == 1 && sorts[0].base == SortBase::None && !sorts[0].rev {
        // no sorting: keep the directory order, but children follow principals
        let mut out: Vec<Node> = Vec::new();
        let mut taken = vec![false; nodes.len()];
        for i in 0..nodes.len() {
            if taken[i] || (nodes[i].child && nodes[i].has_parent) {
                continue;
            }
            taken[i] = true;
            out.push(nodes[i].clone());
            if nodes[i].child {
                continue;
            }
            for j in 0..nodes.len() {
                if taken[j] {
                    continue;
                }
                if nodes[j].child && nodes[j].has_parent {
                    if let Some(p) = kinds::parent_name_of(&nodes[j].name) {
                        if p == nodes[i].name {
                            taken[j] = true;
                            out.push(nodes[j].clone());
                        }
                    }
                }
            }
        }
        for i in 0..nodes.len() {
            if !taken[i] {
                out.push(nodes[i].clone());
            }
        }
        *nodes = out;
        return;
    }
    // build units
    let mut taken = vec![false; nodes.len()];
    let mut units: Vec<Vec<usize>> = Vec::new();
    for i in 0..nodes.len() {
        if taken[i] || (nodes[i].child && nodes[i].has_parent) {
            continue;
        }
        taken[i] = true;
        units.push(vec![i]);
        if nodes[i].child {
            continue;
        }
        for j in 0..nodes.len() {
            if taken[j] {
                continue;
            }
            if nodes[j].child && nodes[j].has_parent {
                if let Some(p) = kinds::parent_name_of(&nodes[j].name) {
                    if p == nodes[i].name {
                        taken[j] = true;
                        units.last_mut().unwrap().push(j);
                    }
                }
            }
        }
